import React from 'react';

import type { CSSObject } from '@emotion/react';
import { omitTransientProps } from 'utils/emotion';

import type { TextAlignment } from '../Heading';
import { StyledParagraph } from './Paragraph.styles';

export type ParagraphSize = 'basis' | 'small' | 'xsmall';
export type ParagraphColorType =
  'primary' | 'secondary' | 'disabled' | 'success' | 'error';
export type ParagraphWeight = 'normal' | 'medium' | 'semibold';

export interface ParagraphProps extends Omit<
  React.HTMLAttributes<HTMLParagraphElement>,
  'color'
> {
  size?: ParagraphSize;
  foreground?: boolean | 'true' | 'false';
  colortype?: ParagraphColorType;
  color?: string;
  marginHeight?: number | string;
  alignment?: TextAlignment;
  weight?: ParagraphWeight;
  selectable?: boolean | 'true' | 'false';
  css?: CSSObject;
}

const toBoolean = (
  value: boolean | 'true' | 'false' | undefined,
  fallback: boolean,
) => (value === undefined ? fallback : value === true || value === 'true');

export const Paragraph = React.forwardRef<HTMLParagraphElement, ParagraphProps>(
  (
    {
      size = 'basis',
      foreground = false,
      colortype = 'primary',
      color,
      alignment = 'left',
      weight = 'normal',
      selectable = true,
      css,
      ...props
    },
    forwardedRef,
  ) => (
    <StyledParagraph
      {...omitTransientProps(props)}
      ref={forwardedRef}
      $alignment={alignment}
      $color={color}
      $colortype={colortype}
      $css={css}
      $foreground={toBoolean(foreground, false)}
      $selectable={toBoolean(selectable, true)}
      $size={size}
      $weight={weight}
    />
  ),
);

Paragraph.displayName = 'Paragraph';
